##### Features/Positions/PositionCalculator.cs
     1	using TradeBlotter.Api.Data;
     2	using TradeBlotter.Api.Features.Trades;
     3	
     4	namespace TradeBlotter.Api.Features.Positions;
     5	
     6	// Average-cost positions, unrounded. Rules: docs/superpowers/specs/2026-10-19-trade-blotter-design.md.
     7	public static class PositionCalculator
     8	{
     9	    public static IReadOnlyList<Position> Calculate(IEnumerable<Trade> trades)
    10	    {
    11	        var positions = new Dictionary<string, (decimal Net, decimal Avg)>();
    12	        foreach (var trade in trades.OrderBy(t => t.Timestamp).ThenBy(t => t.Sequence))
    13	        {
    14	            var (net, avg) = positions.GetValueOrDefault(trade.Symbol);
    15	            positions[trade.Symbol] = Apply(net, avg, trade);
    16	        }
    17	
    18	        return positions
    19	            .Where(p => p.Value.Net != 0)
    20	            .OrderBy(p => p.Key, StringComparer.Ordinal)
    21	            .Select(p => new Position(p.Key, p.Value.Net, p.Value.Avg))
    22	            .ToList();
    23	    }
    24	
    25	    private static (decimal Net, decimal Avg) Apply(decimal net, decimal avg, Trade trade)
    26	    {
    27	        var q = trade.Quantity;
    28	        var signed = trade.Side == Side.Buy ? q : -q;
    29	        var newNet = net + signed;
    30	        var held = Math.Abs(net);
    31	
    32	        if (net == 0 || Math.Sign(net) == Math.Sign(signed))
    33	            return (newNet, (held * avg + q * trade.Price) / (held + q));
    34	        // Reducing keeps the average; flipping through zero opens at this trade's price.
    35	        // Closing to exactly zero keeps a stale average, which the next trade ignores because held is 0.
    36	        return (newNet, q <= held ? avg : trade.Price);
    37	    }
    38	}

